# -*- coding: utf-8 -*-
import re
from pathlib import Path
root = Path(__file__).resolve().parent
fav_html = '<!-- DAEBONG_FAVICON_START -->\n<link rel="icon" type="image/svg+xml" href="/favicon.svg?v=20261029"/>\n<link rel="icon" type="image/png" sizes="192x192" href="/favicon.png?v=20261029"/>\n<link rel="shortcut icon" href="/favicon.ico?v=20261029"/>\n<link rel="apple-touch-icon" href="/favicon.png?v=20261029"/>\n<!-- DAEBONG_FAVICON_END -->'
ui_html = '<!-- DAEBONG_UI_PATCH_START -->\n<style id="daebong-ui-patch-style">.db-extra-hidden{display:none!important}.db-more-container{grid-column:1/-1;width:100%;text-align:center;margin:24px 0 12px 0;display:flex;flex-wrap:wrap;justify-content:center;gap:12px}.db-more-toggle-btn{background:#1d4ed8;color:#fff;border:none;padding:14px 28px;border-radius:999px;font-weight:700;font-size:0.98rem;cursor:pointer;box-shadow:0 4px 12px rgba(29,78,216,0.22)}.db-more-toggle-btn:hover{background:#1e40af}.db-more-archive-link{background:#fff;color:#1d4ed8;border:2px solid #1d4ed8;padding:12px 24px;border-radius:999px;font-weight:700;font-size:0.96rem;text-decoration:none;display:inline-flex;align-items:center}.db-more-archive-link:hover{background:#eff6ff}</style>\n<script id="daebong-ui-patch-script">(function(){function applyCardLimit(){var links=Array.from(document.querySelectorAll("a")).filter(function(a){return(a.textContent||"").indexOf("이 글 전용 페이지")!==-1});if(links.length<=2)return;var cards=[];links.forEach(function(link){var cur=link;while(cur.parentElement&&cur.parentElement!==document.body){var cnt=links.filter(function(l){return cur.parentElement.contains(l)}).length;if(cnt>1)break;cur=cur.parentElement}if(cur&&cards.indexOf(cur)===-1)cards.push(cur)});if(cards.length<=2)return;var parent=cards[0].parentElement;if(!parent)return;var extra=cards.slice(2);extra.forEach(function(c){c.classList.add("db-extra-hidden")});var old=document.getElementById("db-more-box");if(old)old.remove();var box=document.createElement("div");box.id="db-more-box";box.className="db-more-container";var btn=document.createElement("button");btn.type="button";btn.className="db-more-toggle-btn";btn.textContent="📂 다른 지역·작업별 안내 펼쳐보기 (+"+extra.length+"건 더보기)";var open=false;btn.onclick=function(){open=!open;extra.forEach(function(c){if(open)c.classList.remove("db-extra-hidden");else c.classList.add("db-extra-hidden")});btn.textContent=open?"▲ 최신 2건만 간략히 접기":"📂 다른 지역·작업별 안내 펼쳐보기 (+"+extra.length+"건 더보기)"};var alink=document.createElement("a");alink.href="/auto-cases/";alink.className="db-more-archive-link";alink.textContent="🗂️ 전체 누적 기록 목록 페이지로 이동";box.appendChild(btn);box.appendChild(alink);parent.appendChild(box)}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",applyCardLimit)}else{applyCardLimit()}})();</script>\n<!-- DAEBONG_UI_PATCH_END -->'
for hp in list(root.glob('*.html')) + list((root / 'auto-cases').rglob('*.html')):
    if not hp.is_file(): continue
    t = hp.read_text(encoding='utf-8', errors='ignore')
    t = re.sub(r'<!-- DAEBONG_FAVICON_START -->.*?<!-- DAEBONG_FAVICON_END -->\s*', '', t, flags=re.S)
    t = re.sub(r'<!-- DAEBONG_UI_PATCH_START -->.*?<!-- DAEBONG_UI_PATCH_END -->\s*', '', t, flags=re.S)
    t = t.replace('(※ 아래 안내는 동일 유형의 작업을 알아보시는 분들을 위한 공통 참고 기준입니다.)', '')
    t = t.replace('안녕하십니까, 사직동 본점을 중심으로 현장에서 직접 뛰는 대봉개발입니다. 😊', '반갑습니다. 부산·경남 현장을 30년 경력 직영 팀이 직접 발로 뛰며 책임지는 대봉개발입니다.')
    t = t.replace('■ 시작부터 마무리 바닥 정리까지 꼼꼼하게', '■ 현장 여건에 맞춘 안전 해체 및 깔끔한 마무리 정리')
    if '</head>' in t: t = t.replace('</head>', fav_html + '\n</head>', 1)
    if hp.name == 'index.html' and hp.parent == root and '</body>' in t: t = t.replace('</body>', ui_html + '\n</body>', 1)
    hp.write_text(t, encoding='utf-8')
print('✓ [2/3] 홈페이지 최신 2개만 노출 및 더보기 버튼 적용 완료')
